css:
.loader { --accent: var(--loader-color); --accent-2: var(--loader-secondary-color); width: var(--loader-size); height: var(--loader-size); display: grid; grid-template-columns: repeat(3, 1fr); gap: 9%; perspective: 600px; }
.loader span { width: 100%; aspect-ratio: 1; background: linear-gradient(135deg, var(--accent), var(--accent-2)); border-radius: 16%; animation: flip calc(var(--loader-speed) * 2) ease-in-out infinite; }
.loader span:nth-child(1) { animation-delay: 0s; }
.loader span:nth-child(2), .loader span:nth-child(4) { animation-delay: calc(var(--loader-speed) * .14); }
.loader span:nth-child(3), .loader span:nth-child(5), .loader span:nth-child(7) { animation-delay: calc(var(--loader-speed) * .28); }
.loader span:nth-child(6), .loader span:nth-child(8) { animation-delay: calc(var(--loader-speed) * .42); }
.loader span:nth-child(9) { animation-delay: calc(var(--loader-speed) * .56); }
@keyframes flip { 0%, 100% { transform: rotateY(0deg); } 50% { transform: rotateY(180deg); } }
